import{_ as s,o as t,c as o,a2 as a}from"./chunks/framework.Zh78JZbW.js";const n="/kodus-releases/screenshots/amis-accueil.png",i="/kodus-releases/screenshots/amis.png",v=JSON.parse('{"title":"Amis","description":"","frontmatter":{},"headers":[],"relativePath":"guide/amis.md","filePath":"guide/amis.md"}'),r={name:"guide/amis.md"};function u(l,e,d,m,p,c){return t(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="amis" tabindex="-1">Amis <a class="header-anchor" href="#amis" aria-label="Permalink to &quot;Amis&quot;">​</a></h1><p>Ajoutez vos amis avec leur pseudo Kodus : vous voyez qui est en ligne et, s&#39;ils le souhaitent, à quoi ils jouent.</p><p>Vos amis s&#39;affichent à droite de l&#39;accueil : qui est en ligne, à quoi ils jouent, et les demandes reçues, que vous pouvez accepter (✓) ou refuser (✕) directement. Si la fenêtre de Kodus est étroite, ce panneau est remplacé par le bouton <strong>Amis</strong> en haut de l&#39;accueil (l&#39;icône à deux personnages).</p><p><img src="'+n+'" alt="Accueil de Kodus : panneau Amis à droite avec une demande reçue et la présence des amis"></p><p>Le bouton <strong>Gérer</strong> du panneau ouvre la page <strong>Amis</strong> complète : demandes envoyées, joueurs bloqués et réglage de votre présence.</p><p><img src="'+i+'" alt="Page Amis : liste d&#39;amis avec leur présence, ajout d&#39;un ami et demandes reçues"></p><h2 id="ajouter-un-ami" tabindex="-1">Ajouter un ami <a class="header-anchor" href="#ajouter-un-ami" aria-label="Permalink to &quot;Ajouter un ami&quot;">​</a></h2><ol><li>Saisissez le pseudo de votre ami dans le champ <strong>Ajouter un ami</strong> (en bas du panneau de l&#39;accueil, ou sur la page Amis), puis validez.</li><li>Votre ami voit la demande dans <strong>Demandes reçues</strong> et choisit <strong>Accepter</strong> ou <strong>Refuser</strong>.</li></ol><p>Si votre ami vous avait déjà envoyé une demande, vous devenez amis tout de suite.</p><ul><li>Vous pouvez envoyer <strong>4 demandes par jour</strong>.</li><li>Votre ami doit utiliser Kodus 0.5 ou plus récent.</li><li>Quand la fenêtre est étroite, un chiffre sur le bouton <strong>Amis</strong> indique les demandes en attente, et un point vert signale qu&#39;un ami est en ligne.</li></ul><h2 id="ce-que-vos-amis-voient" tabindex="-1">Ce que vos amis voient <a class="header-anchor" href="#ce-que-vos-amis-voient" aria-label="Permalink to &quot;Ce que vos amis voient&quot;">​</a></h2><p>En haut à droite de la page, <strong>Ma présence</strong> règle ce que vos amis voient de vous :</p><table tabindex="0"><thead><tr><th>Réglage</th><th>Ce que vos amis voient</th></tr></thead><tbody><tr><td><strong>Tout montrer</strong></td><td>Si vous êtes en ligne, et l&#39;instance à laquelle vous jouez (« En jeu : Create (1.21.1 NeoForge) »)</td></tr><tr><td><strong>En ligne seulement</strong> (par défaut)</td><td>Seulement si vous êtes en ligne, pas à quoi vous jouez</td></tr><tr><td><strong>Invisible</strong></td><td>Vous apparaissez toujours hors ligne</td></tr></tbody></table><p>Seuls vos amis voient votre présence. Elle se met à jour environ toutes les minutes.</p><p>Une partie que vous ouvrez avec <a href="./jouer-ensemble">Jouer ensemble</a> est visible par vos amis même en « En ligne seulement », mais pas en « Invisible ». Vos amis voient aussi les instances que vous partagez.</p><h2 id="retirer-ou-bloquer" tabindex="-1">Retirer ou bloquer <a class="header-anchor" href="#retirer-ou-bloquer" aria-label="Permalink to &quot;Retirer ou bloquer&quot;">​</a></h2><p>Passez la souris sur un ami pour afficher <strong>Retirer</strong> et <strong>Bloquer</strong>.</p><ul><li><strong>Retirer</strong> : vous n&#39;êtes plus amis. Il peut vous renvoyer une demande.</li><li><strong>Bloquer</strong> : vous n&#39;êtes plus amis et il ne peut plus vous envoyer de demande. Il n&#39;en est pas averti.</li></ul><p>Vous pouvez aussi bloquer un joueur depuis une demande reçue. La liste <strong>Joueurs bloqués</strong>, en bas à droite, permet de les débloquer.</p><h2 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h2><p>Kodus vous prévient quand vous recevez une demande d&#39;ami et quand un joueur accepte la vôtre : une notification Windows ou macOS si Kodus est en arrière-plan, un petit message dans Kodus sinon.</p><p>Dans <strong>Paramètres</strong> → onglet <strong>Notifications</strong>, vous pouvez :</p><ul><li>désactiver les notifications de demandes d&#39;ami ;</li><li>activer une notification quand un ami se connecte (désactivée par défaut).</li><li>désactiver la notification quand un ami ouvre une partie (voir <a href="./jouer-ensemble">Jouer ensemble</a>), activée par défaut.</li></ul><p>Le bouton <strong>Tester les notifications</strong> vérifie qu&#39;elles s&#39;affichent. Si rien n&#39;apparaît sous Windows : <strong>Paramètres Windows</strong> → <strong>Système</strong> → <strong>Notifications</strong>, vérifiez que Kodus est autorisé et que <strong>Ne pas déranger</strong> est désactivé. La version portable ajoute pour cela un raccourci Kodus dans le menu Démarrer : Windows n&#39;affiche les notifications que des applications qui en ont un.</p>',24)])])}const h=s(r,[["render",u]]);export{v as __pageData,h as default};
